// MG18 quarantined native DK16 boundary bridge: actual original public JSON only.
// No environment actions generated by this bridge; no mission substitution.
package main
import (
 "bufio"
 "bytes"
 "encoding/base64"
 "encoding/json"
 "errors"
 "fmt"
 "io"
 "os"
 native "github.com/spoonman136668-ai/Wingless/research/native/itd02/dk16"
)
type Request struct {
 Op string `json:"op"`
 Before json.RawMessage `json:"before,omitempty"`
 After json.RawMessage `json:"after,omitempty"`
 Action int `json:"action,omitempty"`
 Reward float64 `json:"reward,omitempty"`
 Terminal bool `json:"terminal,omitempty"`
 State string `json:"state,omitempty"`
}
type Reply struct {
 OK bool `json:"ok"`
 Action *int `json:"action,omitempty"`
 Status string `json:"status,omitempty"`
 Updates uint64 `json:"updates,omitempty"`
 State string `json:"state,omitempty"`
 Error string `json:"error,omitempty"`
}
func strict(raw []byte,out any)error{
 d:=json.NewDecoder(bytes.NewReader(raw));d.DisallowUnknownFields()
 if e:=d.Decode(out);e!=nil{return e}
 if d.Decode(new(any))!=io.EOF{return errors.New("MG18_TRAILING_SOURCE")}
 return nil
}
func originalPublic(raw json.RawMessage)(native.Public,error){
 var p native.Public
 if len(raw)==0{return p,errors.New("MG18_PUBLIC_REQUIRED")}
 if e:=strict(raw,&p);e!=nil{return p,e}
 if len(p.Mission)==0{return p,errors.New("MG18_EMPTY_ORIGINAL_MISSION")}
 // Validate source 7x7x3 image and heading using unchanged native public
 // without changing the actual mission delivered to DK16.
 legacy:=p;legacy.Mission="use the key to open the door and then get to the goal"
 if e:=legacy.Valid();e!=nil{return p,e}
 return p,nil
}
func process(m **native.Policy,q Request)(Reply,bool){
 r:=Reply{};p:=*m;var e error
 switch q.Op{
 case "begin_episode":e=p.BeginEpisode()
 case "choose":
  var v native.Public;v,e=originalPublic(q.Before)
  if e==nil{r.Action,r.Status,e=p.Choose(v)}
 case "commit":
  var v native.Public;v,e=originalPublic(q.Before)
  if e==nil{e=p.Commit(v,q.Action)}
 case "feedback":
  var b,a native.Public;b,e=originalPublic(q.Before)
  if e==nil{a,e=originalPublic(q.After)}
  if e==nil{e=p.Feedback(b,q.Action,a,q.Reward,q.Terminal)}
 case "snapshot":
  var b []byte;b,e=p.Snapshot()
  if e==nil{r.State=base64.StdEncoding.EncodeToString(b)}
 case "load":
  var b []byte;b,e=base64.StdEncoding.DecodeString(q.State)
  if e==nil{var v *native.Policy;v,e=native.Restore(b);if e==nil{*m=v;p=v}}
 case "quit":r.OK=true;return r,true
 default:e=errors.New("MG18_UNREGISTERED_OPERATION")
 }
 if e!=nil{r.Error=e.Error();return r,false}
 r.OK=true;r.Updates=p.Agent.Samples
 return r,false
}
func serve(in io.Reader,out io.Writer)error{
 scan:=bufio.NewScanner(in);scan.Buffer(make([]byte,4096),8<<20)
 writer:=bufio.NewWriter(out);p:=native.New()
 for scan.Scan(){
  var req Request;var rep Reply;exit:=false
  if e:=strict(scan.Bytes(),&req);e!=nil{rep.Error=e.Error()}else{rep,exit=process(&p,req)}
  raw,e:=json.Marshal(rep);if e!=nil{return e}
  if _,e=writer.Write(append(raw,'\n'));e!=nil{return e}
  if e=writer.Flush();e!=nil{return e}
  if exit{return nil}
 }
 return scan.Err()
}
func main(){if e:=serve(os.Stdin,os.Stdout);e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(2)}}
